public static List<T> CreateMany<T>(int n) where T : new()
{
    var list = new List<T>(n);
    for (int i = 0; i < n; i++) list.Add(new T());
    return list;
}

public interface IRepository<T> where T : class
{
    T? Get(int id);
    void Add(T entity);
}

public T? GetOrDefault<T>(IList<T> items, int index)
{
    return index >= 0 && index < items.Count ? items[index] : default;
}

public static T Sum<T>(IEnumerable<T> values) where T : INumber<T>
{
    T total = T.Zero;
    foreach (var v in values) total += v;
    return total;
}

static T Average<T>(IEnumerable<T> xs) where T : INumber<T>
{
    T sum = T.Zero; int n = 0;
    foreach (var x in xs) { sum += x; n++; }
    return sum / T.CreateChecked(n);
}

